CREATE TABLE public.hr_payroll_months(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),year integer NOT NULL,month integer NOT NULL CHECK(month BETWEEN 1 AND 12),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved')),prepared_by uuid,prepared_at timestamptz,approved_by uuid,approved_at timestamptz,revision integer NOT NULL DEFAULT 0,UNIQUE(tenant_id,year,month));
GRANT SELECT ON public.hr_payroll_months TO authenticated; GRANT ALL ON public.hr_payroll_months TO service_role; ALTER TABLE public.hr_payroll_months ENABLE ROW LEVEL SECURITY;
CREATE POLICY payroll_month_read ON public.hr_payroll_months FOR SELECT TO authenticated USING(public.people_access(tenant_id,auth.uid()));
CREATE TABLE public.hr_payroll_overrides(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),employee_id uuid NOT NULL REFERENCES public.hr_employees(id),payroll_id uuid NOT NULL REFERENCES public.hr_payroll(id),field text NOT NULL CHECK(field IN ('adjustments_override','earned_salary_override','actual_overtime','actual_bonus','forecast_allowances')),previous_value numeric NOT NULL,new_value numeric NOT NULL,reason text NOT NULL CHECK(length(reason) BETWEEN 1 AND 3000),repeat boolean NOT NULL DEFAULT false,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.hr_payroll_overrides TO authenticated; GRANT ALL ON public.hr_payroll_overrides TO service_role; ALTER TABLE public.hr_payroll_overrides ENABLE ROW LEVEL SECURITY;
CREATE POLICY payroll_override_read ON public.hr_payroll_overrides FOR SELECT TO authenticated USING(public.people_person_access(tenant_id,employee_id,auth.uid()));
CREATE TABLE public.hr_payslips(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id),payroll_id uuid NOT NULL UNIQUE REFERENCES public.hr_payroll(id),employee_id uuid NOT NULL REFERENCES public.hr_employees(id),snapshot jsonb NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.hr_payslips TO authenticated; GRANT ALL ON public.hr_payslips TO service_role; ALTER TABLE public.hr_payslips ENABLE ROW LEVEL SECURITY;
CREATE POLICY payroll_payslip_read ON public.hr_payslips FOR SELECT TO authenticated USING(public.people_person_access(tenant_id,employee_id,auth.uid()));
ALTER TABLE public.hr_payroll ADD COLUMN preparation jsonb;
CREATE FUNCTION public.payroll_manager(t uuid,u uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.people_access(t,u) AND NOT EXISTS(SELECT 1 FROM public.user_page_permissions WHERE tenant_id=t AND user_id=u AND page_key='people' AND (NOT can_access OR authority='view_only')) $$;
REVOKE ALL ON FUNCTION public.payroll_manager(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.payroll_manager(uuid,uuid) TO authenticated,service_role;
CREATE POLICY payroll_person_scope ON public.hr_payroll AS RESTRICTIVE FOR ALL TO authenticated USING(public.people_person_access(tenant_id,employee_id,auth.uid())) WITH CHECK(public.payroll_manager(tenant_id,auth.uid()) AND public.people_person_access(tenant_id,employee_id,auth.uid()));
CREATE FUNCTION public.payroll_preview(t uuid,y integer,m integer) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
DECLARE e record;p public.hr_payroll;v uuid;settings jsonb;terms jsonb;d date;first_day date:=make_date(y,m,1);last_day date:=(make_date(y,m,1)+interval '1 month -1 day')::date;today date:=(now() AT TIME ZONE 'Asia/Hong_Kong')::date;nd integer;earned numeric;hours numeric;total_hours numeric;daily numeric;rate numeric;basis text;unpaid numeric;leave_pay numeric;leave_days numeric;gross numeric;ee numeric;er numeric;net numeric;reasons jsonb;missing jsonb;result jsonb:='[]';kind text;paid boolean;source text;expected integer;confirmed integer;legacy boolean;rep record;
BEGIN
IF NOT public.people_access(t,auth.uid()) OR y NOT BETWEEN 2000 AND 2200 THEN RAISE EXCEPTION 'People access and valid period required';END IF;nd:=last_day-first_day+1;
FOR e IN SELECT * FROM public.hr_employees WHERE tenant_id=t AND hire_date<=last_day AND (end_date IS NULL AND status IN ('active','on_leave') OR end_date>=first_day) AND public.people_person_access(t,id,auth.uid()) UNION SELECT e.* FROM public.hr_employees e WHERE e.tenant_id=t AND public.people_person_access(t,e.id,auth.uid()) AND EXISTS(SELECT 1 FROM public.hr_payroll p WHERE p.tenant_id=t AND p.employee_id=e.id AND year=y AND month=m) AND NOT(e.hire_date<=last_day AND (e.end_date IS NULL AND e.status IN ('active','on_leave') OR e.end_date>=first_day)) LOOP
SELECT * INTO p FROM public.hr_payroll WHERE tenant_id=t AND employee_id=e.id AND year=y AND month=m;
v:=COALESCE(NULLIF(public.people_terms_at(t,e.id,last_day)->>'venue_id','')::uuid,e.venue_id);settings:=public.people_effective_settings(t,v);source:=settings->>'pay_hours';earned:=0;unpaid:=0;leave_pay:=0;leave_days:=0;total_hours:=0;expected:=0;confirmed:=0;reasons:='[]';missing:='[]';legacy:=p.id IS NOT NULL AND p.preparation IS NULL;
IF e.hire_date BETWEEN first_day AND last_day THEN reasons:=reasons||jsonb_build_array('Joined '||to_char(e.hire_date,'DD Mon')||', paid for '||(least(COALESCE(e.end_date,last_day),last_day)-e.hire_date+1)||' days');END IF;
FOR d IN SELECT generate_series(first_day,last_day,interval '1 day')::date LOOP
terms:=public.people_terms_at(t,e.id,d);IF COALESCE(NULLIF(terms->>'hire_date','')::date,e.hire_date)>d OR COALESCE(NULLIF(terms->>'end_date','')::date,e.end_date,last_day)<d THEN CONTINUE;END IF;
rate:=NULLIF(terms->>'pay_amount','')::numeric;basis:=COALESCE(terms->>'pay_basis',CASE WHEN e.employment_type='full_time' THEN 'month' ELSE 'hour' END);
IF rate IS NULL AND p.id IS NOT NULL THEN rate:=p.forecast_base_salary;END IF;
IF rate IS NULL THEN IF NOT missing ? 'Pay terms not recorded' THEN missing:=missing||jsonb_build_array('Pay terms not recorded');END IF;CONTINUE;END IF;
hours:=0;
IF source='rota' THEN SELECT COALESCE(sum(greatest(0,extract(epoch from(CASE WHEN end_time<start_time THEN end_time-start_time+interval '24 hours' ELSE end_time-start_time END))/3600-break_minutes/60.0)),0) INTO hours FROM public.hr_shifts WHERE tenant_id=t AND employee_id=e.id AND shift_date=d AND shift_type='regular';
ELSIF source='clock_ins' THEN SELECT COALESCE(sum(hours_worked) FILTER(WHERE confirmed_at IS NOT NULL AND clock_out IS NOT NULL),0) INTO hours FROM public.hr_attendance WHERE tenant_id=t AND employee_id=e.id AND date=d;
IF d<=today AND EXISTS(SELECT 1 FROM public.hr_shifts WHERE tenant_id=t AND employee_id=e.id AND shift_date=d AND shift_type='regular') THEN expected:=expected+1;IF EXISTS(SELECT 1 FROM public.hr_attendance WHERE tenant_id=t AND employee_id=e.id AND date=d AND confirmed_at IS NOT NULL AND clock_out IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM public.hr_attendance WHERE tenant_id=t AND employee_id=e.id AND date=d AND (confirmed_at IS NULL OR clock_out IS NULL)) THEN confirmed:=confirmed+1;END IF;END IF;
ELSE IF basis='hour' THEN IF p.id IS NULL THEN IF NOT missing ? 'Monthly hours not typed' THEN missing:=missing||jsonb_build_array('Monthly hours not typed');END IF;ELSE hours:=p.forecast_allowances/nd;END IF;END IF;END IF;
total_hours:=total_hours+hours;daily:=CASE WHEN basis='month' THEN rate/nd ELSE rate*hours END;
SELECT lt.name,lt.is_paid INTO kind,paid FROM public.hr_leave_requests lr JOIN public.hr_leave_types lt ON lt.id=lr.leave_type_id AND lt.tenant_id=t WHERE lr.tenant_id=t AND lr.employee_id=e.id AND lr.status='approved' AND d BETWEEN lr.start_date AND lr.end_date ORDER BY lr.id LIMIT 1;
IF kind IS NULL THEN SELECT CASE shift_type WHEN 'NPL' THEN 'Unpaid' WHEN 'SL' THEN 'Sick' WHEN 'AL' THEN 'Annual' WHEN 'SH' THEN 'Statutory' END,shift_type<>'NPL' INTO kind,paid FROM public.hr_shifts WHERE tenant_id=t AND employee_id=e.id AND shift_date=d AND shift_type IN ('NPL','SL','AL','SH') LIMIT 1;END IF;
IF kind IS NOT NULL THEN IF basis='month' AND NOT paid THEN unpaid:=unpaid+daily;ELSIF basis='hour' AND paid THEN IF terms->>'daily_hours' IS NULL THEN IF NOT missing ? 'Paid leave hours need review' THEN missing:=missing||jsonb_build_array('Paid leave hours need review');END IF;ELSE daily:=rate*(terms->>'daily_hours')::numeric;END IF;END IF;IF lower(kind) LIKE '%sick%' THEN IF NOT reasons ? 'Sick leave recorded; check paid entitlement' THEN reasons:=reasons||jsonb_build_array('Sick leave recorded; check paid entitlement');END IF;END IF;END IF;
earned:=earned+daily;
END LOOP;
IF expected>confirmed AND source='clock_ins' THEN missing:=missing||jsonb_build_array((expected-confirmed)||' days waiting for a manager');END IF;
IF source='clock_ins' AND settings->>'clock_in'='off' THEN missing:=missing||jsonb_build_array('Clock-ins are off but selected for pay');END IF;
IF source='rota' AND NOT(settings->>'rota')::boolean THEN missing:=missing||jsonb_build_array('Rota is off but selected for pay');END IF;
IF total_hours=0 AND COALESCE(terms->>'pay_basis',CASE WHEN e.employment_type='full_time' THEN 'month' ELSE 'hour' END)='hour' AND source<>'typed_monthly' THEN missing:=missing||jsonb_build_array('No hours recorded');END IF;
IF e.end_date BETWEEN first_day AND last_day THEN
SELECT COALESCE(sum(greatest(0,COALESCE(b.carried_forward,0)+b.total_days+COALESCE(b.adjustments,0)-b.used_days)),0) INTO leave_days FROM public.hr_leave_balances b JOIN public.hr_leave_types lt ON lt.id=b.leave_type_id AND lt.tenant_id=t WHERE b.tenant_id=t AND b.employee_id=e.id AND b.year=y AND lower(lt.name) LIKE '%annual%';
IF NOT EXISTS(SELECT 1 FROM public.hr_leave_balances b JOIN public.hr_leave_types lt ON lt.id=b.leave_type_id WHERE b.tenant_id=t AND b.employee_id=e.id AND b.year=y AND lower(lt.name) LIKE '%annual%') THEN missing:=missing||jsonb_build_array('Final annual leave balance not recorded');END IF;
IF terms->>'pay_amount' IS NOT NULL THEN leave_pay:=leave_days*CASE WHEN terms->>'pay_basis'='hour' THEN (terms->>'pay_amount')::numeric*COALESCE(NULLIF(terms->>'daily_hours','')::numeric,0) ELSE (terms->>'pay_amount')::numeric/nd END;END IF;
reasons:=reasons||jsonb_build_array('Left '||to_char(e.end_date,'DD Mon')||': final pay including '||leave_days||' days leave');END IF;
IF p.id IS NOT NULL THEN earned:=COALESCE(p.earned_salary_override,p.actual_base_salary,CASE WHEN e.employment_type='full_time' THEN p.forecast_base_salary ELSE p.forecast_base_salary*p.forecast_allowances END);unpaid:=p.unpaid_leave_deduction;leave_pay:=p.annual_leave_pay;IF legacy THEN reasons:=reasons||jsonb_build_array('Existing saved payroll kept; verify against contracts');END IF;END IF;
gross:=earned+COALESCE(p.actual_overtime,0)+COALESCE(p.actual_bonus,0)+leave_pay-unpaid+COALESCE(p.adjustments_override,0);ee:=COALESCE(p.mpf_employee_override,least(1500,gross*0.05));er:=COALESCE(p.mpf_employer_override,least(1500,gross*0.05));net:=gross-ee-COALESCE(p.other_deductions,0);
IF p.id IS NOT NULL THEN gross:=p.gross_salary;ee:=p.mpf_employee;er:=p.mpf_employer;net:=p.net_salary;END IF;
result:=result||jsonb_build_array(COALESCE(to_jsonb(p),'{}')||jsonb_build_object('id',p.id,'employee_id',e.id,'name',e.first_name||' '||e.last_name,'venue_id',v,'year',y,'month',m,'forecast_base_salary',COALESCE(p.forecast_base_salary,NULLIF(terms->>'pay_amount','')::numeric,0),'forecast_allowances',CASE WHEN e.employment_type='full_time' THEN nd ELSE total_hours END,'earned_salary_override',earned,'annual_leave_pay',leave_pay,'unpaid_leave_deduction',unpaid,'gross_salary',gross,'mpf_employee',ee,'mpf_employer',er,'net_salary',net,'mpf_payment_amount',ee+er,'preparation',jsonb_build_object('source',source,'hours',total_hours,'expected_days',expected,'confirmed_days',confirmed,'reasons',reasons,'missing',missing)));
END LOOP;RETURN result;END $$;
REVOKE ALL ON FUNCTION public.payroll_preview(uuid,integer,integer) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.payroll_preview(uuid,integer,integer) TO authenticated;
CREATE FUNCTION public.payroll_prepare(t uuid,y integer,m integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb;result jsonb;BEGIN
IF NOT public.payroll_manager(t,auth.uid()) THEN RAISE EXCEPTION 'Payroll manager access required';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(t::text||y||'-'||m,0));IF EXISTS(SELECT 1 FROM public.hr_payroll_months WHERE tenant_id=t AND year=y AND month=m AND status='approved') THEN RETURN public.payroll_preview(t,y,m);END IF;
result:=public.payroll_preview(t,y,m);FOR r IN SELECT value FROM jsonb_array_elements(result) LOOP
IF r->>'id' IS NULL AND jsonb_array_length(r->'preparation'->'missing')=0 THEN INSERT INTO public.hr_payroll(tenant_id,employee_id,year,month,forecast_base_salary,forecast_allowances,earned_salary_override,annual_leave_pay,unpaid_leave_deduction,gross_salary,mpf_employee,mpf_employer,net_salary,mpf_payment_amount,total_deductions,payment_status,preparation) VALUES(t,(r->>'employee_id')::uuid,y,m,(r->>'forecast_base_salary')::numeric,(r->>'forecast_allowances')::numeric,(r->>'earned_salary_override')::numeric,(r->>'annual_leave_pay')::numeric,(r->>'unpaid_leave_deduction')::numeric,(r->>'gross_salary')::numeric,(r->>'mpf_employee')::numeric,(r->>'mpf_employer')::numeric,(r->>'net_salary')::numeric,(r->>'mpf_payment_amount')::numeric,(r->>'mpf_employee')::numeric,'draft',r->'preparation');END IF;END LOOP;
INSERT INTO public.hr_payroll_months(tenant_id,year,month,prepared_by,prepared_at,revision) VALUES(t,y,m,auth.uid(),now(),1) ON CONFLICT(tenant_id,year,month) DO UPDATE SET prepared_by=EXCLUDED.prepared_by,prepared_at=now(),revision=hr_payroll_months.revision+1;RETURN public.payroll_preview(t,y,m);END $$;
REVOKE ALL ON FUNCTION public.payroll_prepare(uuid,integer,integer) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.payroll_prepare(uuid,integer,integer) TO authenticated;
CREATE FUNCTION public.payroll_override(t uuid,pid uuid,f text,value numeric,previous numeric,why text,repeating boolean,rev integer) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.hr_payroll;v uuid;s jsonb;old numeric;earned numeric;gross numeric;ee numeric;er numeric;BEGIN
SELECT * INTO p FROM public.hr_payroll WHERE id=pid AND tenant_id=t FOR UPDATE;IF p.id IS NULL OR NOT public.payroll_manager(t,auth.uid()) OR NOT public.people_person_access(t,p.employee_id,auth.uid()) THEN RAISE EXCEPTION 'Payroll person access required';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(t::text||p.year||'-'||p.month,0));IF EXISTS(SELECT 1 FROM public.hr_payroll_months WHERE tenant_id=t AND year=p.year AND month=p.month AND (status='approved' OR revision<>rev)) OR p.accrual_journal_entry_id IS NOT NULL OR p.salary_paid_amount>0 OR p.mpf_paid_amount>0 THEN RAISE EXCEPTION 'Payroll changed or locked; reload';END IF;
v:=COALESCE(NULLIF(public.people_terms_at(t,p.employee_id,make_date(p.year,p.month,1))->>'venue_id','')::uuid,(SELECT venue_id FROM public.hr_employees WHERE id=p.employee_id));s:=public.people_effective_settings(t,v);IF NOT public.people_owner(t,auth.uid()) AND NOT(s->>'managers_change_pay')::boolean THEN RAISE EXCEPTION 'Managers cannot change pay';END IF;
IF f NOT IN ('adjustments_override','earned_salary_override','actual_overtime','actual_bonus','forecast_allowances') OR value IS NULL OR value::text IN ('NaN','Infinity','-Infinity') OR abs(value)>10000000 OR why IS NULL OR length(trim(why)) NOT BETWEEN 1 AND 3000 THEN RAISE EXCEPTION 'Invalid payroll change';END IF;
IF f='forecast_allowances' AND s->>'pay_hours'<>'typed_monthly' THEN RAISE EXCEPTION 'Hours come from rota or confirmed clock-ins';END IF;
old:=COALESCE((to_jsonb(p)->>f)::numeric,0);IF old<>previous THEN RAISE EXCEPTION 'Figure changed; reload';END IF;
EXECUTE format('UPDATE public.hr_payroll SET %I=$1 WHERE id=$2 AND tenant_id=$3',f) USING value,pid,t;
SELECT * INTO p FROM public.hr_payroll WHERE id=pid AND tenant_id=t;earned:=COALESCE(p.earned_salary_override,p.actual_base_salary,p.forecast_base_salary);IF f='forecast_allowances' THEN earned:=p.forecast_base_salary*value;UPDATE public.hr_payroll SET earned_salary_override=earned WHERE id=pid;END IF;gross:=earned+COALESCE(p.actual_overtime,0)+COALESCE(p.actual_bonus,0)+p.annual_leave_pay-p.unpaid_leave_deduction+COALESCE(p.adjustments_override,0);ee:=COALESCE(p.mpf_employee_override,least(1500,gross*0.05));er:=COALESCE(p.mpf_employer_override,least(1500,gross*0.05));
UPDATE public.hr_payroll SET gross_salary=gross,mpf_employee=ee,mpf_employer=er,net_salary=gross-ee-p.other_deductions,total_deductions=ee+p.other_deductions,mpf_payment_amount=ee+er WHERE id=pid AND tenant_id=t;
INSERT INTO public.hr_payroll_overrides(tenant_id,employee_id,payroll_id,field,previous_value,new_value,reason,repeat,created_by) VALUES(t,p.employee_id,pid,f,old,value,why,repeating,auth.uid());UPDATE public.hr_payroll_months SET prepared_by=auth.uid(),prepared_at=now(),revision=revision+1 WHERE tenant_id=t AND year=p.year AND month=p.month;END $$;
REVOKE ALL ON FUNCTION public.payroll_override(uuid,uuid,text,numeric,numeric,text,boolean,integer) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.payroll_override(uuid,uuid,text,numeric,numeric,text,boolean,integer) TO authenticated;
CREATE FUNCTION public.payroll_lock_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t uuid;e uuid;y integer;m integer;BEGIN t:=COALESCE(NEW.tenant_id,OLD.tenant_id);e:=COALESCE(NEW.employee_id,OLD.employee_id);y:=COALESCE(NEW.year,OLD.year);m:=COALESCE(NEW.month,OLD.month);PERFORM pg_advisory_xact_lock(hashtextextended(t::text||y||'-'||m,0));IF EXISTS(SELECT 1 FROM public.hr_payroll_months WHERE tenant_id=t AND year=y AND month=m AND status='approved') THEN
IF TG_OP<>'UPDATE' OR (to_jsonb(NEW)-ARRAY['updated_at','payment_status','payment_date','net_salary_payment_date','mpf_payment_date','salary_paid_amount','mpf_paid_amount']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['updated_at','payment_status','payment_date','net_salary_payment_date','mpf_payment_date','salary_paid_amount','mpf_paid_amount']) THEN RAISE EXCEPTION 'Approved payroll is locked; financial corrections require review';END IF;END IF;
IF current_setting('role',true) IN ('authenticated','anon') AND TG_OP='UPDATE' AND (to_jsonb(NEW)-ARRAY['updated_at','payment_status','payment_date','net_salary_payment_date','mpf_payment_date','salary_paid_amount','mpf_paid_amount']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['updated_at','payment_status','payment_date','net_salary_payment_date','mpf_payment_date','salary_paid_amount','mpf_paid_amount']) THEN RAISE EXCEPTION 'Use confirmed payroll changes';END IF;IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;END $$;
CREATE TRIGGER payroll_month_lock BEFORE INSERT OR UPDATE OR DELETE ON public.hr_payroll FOR EACH ROW EXECUTE FUNCTION public.payroll_lock_guard();